use xiom.io;

type Age = {
  years: Int;
  invariant: years >= 0;
  invariant: years <= 150;
}

fn Age.is_adult(self: &Self) -> Bool {
  return self.years >= 18;
}

fn Age.next_birthday(self: &Self) -> Age {
  if self.years >= 150 { return Age{ years: self.years }; }
  return Age{ years: self.years + 1 };
}

fn Age.can_drive(self: &Self) -> Bool {
  return self.years >= 16;
}

fn Age.can_vote(self: &Self) -> Bool {
  return self.years >= 18;
}

fn main() -> Int {
  let me: Age = Age{ years: 25 };
  io.println("Can drive: " + me.can_drive().to_str());
  io.println("Can vote: " + me.can_vote().to_str());
  return 0;
}
